head.script:
scwin.onpageload = function() {
    scwin.tabIndex = 1;
    console.log("[tabControl_main_wframeMode.xml] scwin.onpageload");
    WebSquare.logger.printLog("[tabControl_main_wframeMode.xml] scwin.onpageload");
};
scwin.onpageunload = function() {};
scwin.addTab = function(tabId, label) {
    var tabOpt = {
        label: label,
        closable: false,
        addTabIndex: 0
    };
    var contOpt = {
        frameMode: "wframePreload",
        scope: true,
        src: label + ".xml",
        alwaysDraw: false,
        title: tabId
    };
    tac_main.addTab(tabId, tabOpt, contOpt);
};
scwin.btn_trigger1_onclick = function(e) {
    var tabId = "tab" + scwin.tabIndex;
    var label = "tabControl_ontabload_WPFF-293_(WSQ-3681)_tab" + scwin.tabIndex;
    scwin.addTab(tabId, label);
    tac_main.setSelectedTabIndex(tabId);
    scwin.tabIndex++;
};
scwin.tac_main_ondrawcomplete = function(tabID, idx, userID) {
    //debugger;
    console.log("scwin.tac_main_ondrawcomplete");
    WebSquare.logger.printLog("scwin.tac_main_ondrawcomplete");
};
scwin.tac_main_ontabload = function(tabID, idx, userID) {
    //debugger;
    console.log("scwin.tac_main_ontabload");
    WebSquare.logger.printLog("scwin.tac_main_ontabload");
};
scwin._checkLog = function() {
    var log = WebSquare.logger.getLog();
    return (log.indexOf("scwin.tac_main_ondrawcomplete") != -1) && (log.indexOf("scwin.tac_main_ontabload") != -1);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click();");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
